create role anon nologin;create role authenticated nologin;
create schema auth;create schema cbgpu_accounts;
create table auth.users(id uuid primary key,raw_user_meta_data jsonb default '{}',email_confirmed_at timestamptz default now(),deleted_at timestamptz,banned_until timestamptz);
create table auth.sessions(id uuid primary key,user_id uuid references auth.users,not_after timestamptz);
create table public.profiles(id uuid primary key references auth.users,full_name text,school_id text default 'cbsh',account_type text default 'STUDENT',account_status text default 'ACTIVE',affiliation_verified boolean default true,is_admin boolean default false,student_id text,student_id_school_year integer,department text,verified_at timestamptz);
create function auth.uid() returns uuid language sql stable as $$select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;
create function cbgpu_accounts.current_session_valid() returns boolean language sql stable as $$select exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where u.id=auth.uid() and s.id=(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'session_id')::uuid and(s.not_after is null or s.not_after>now()) and u.deleted_at is null and(u.banned_until is null or u.banned_until<=now()))$$;
insert into auth.users(id) select ('00000000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid from generate_series(1,5)x;
insert into auth.sessions(id,user_id) select ('10000000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,('00000000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid from generate_series(1,5)x;
insert into public.profiles(id,full_name,is_admin,student_id) select id,'fixture',id='00000000-0000-4000-8000-000000000001',case when id='00000000-0000-4000-8000-000000000001' then '1101' else null end from auth.users;
update public.profiles set account_type='EXTERNAL',affiliation_verified=false where id='00000000-0000-4000-8000-000000000002';
update public.profiles set account_status='SUSPENDED' where id='00000000-0000-4000-8000-000000000003';
update public.profiles set account_type='TEACHER' where id='00000000-0000-4000-8000-000000000004';
create table cbgpu_accounts.guest_requests(id uuid primary key default gen_random_uuid(),external_user_id uuid,requester_id uuid,school_id text,status text,starts_at timestamptz,ends_at timestamptz,resources text[]);
-- Existing application schemas/policies, modeled with real PostgreSQL RLS.
create schema storage;create table storage.objects(id uuid default gen_random_uuid(),bucket_id text,name text);alter table storage.objects enable row level security;grant all on storage.objects to authenticated;
create table public.contests(id uuid primary key default gen_random_uuid(),host_id uuid references public.profiles,title text,description text,banner_path text,event_start_at timestamptz,event_end_at timestamptz,registration_open boolean,registration_closes_at timestamptz,location_type text,location_name text,lifecycle_status text default 'published',participation_mode text,team_min_size integer,team_max_size integer,created_at timestamptz default now());
create table public.event_hosts(contest_id uuid,user_id uuid);
create table public.event_registrations(id uuid primary key default gen_random_uuid(),contest_id uuid,user_id uuid,status text,created_at timestamptz default now());
create table public.research_notes(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles,is_shared boolean,title text);
create table public.shared_materials(id uuid primary key default gen_random_uuid(),uploader_id uuid references public.profiles,title text,status text);
create table public.cpu_projects(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles,title text);
alter table public.contests enable row level security;alter table public.research_notes enable row level security;alter table public.shared_materials enable row level security;alter table public.cpu_projects enable row level security;
grant usage on schema auth,storage to authenticated;
grant select,insert,update on public.contests,public.research_notes,public.shared_materials,public.cpu_projects to authenticated;
create policy contests_read on public.contests for select to authenticated using(true);
create policy contests_create on public.contests for insert to authenticated with check(host_id=auth.uid());
create policy contests_update on public.contests for update to authenticated using(host_id=auth.uid());
create policy notes_own on public.research_notes to authenticated using(user_id=auth.uid());
create policy notes_shared on public.research_notes for select to authenticated using(is_shared);
create policy materials_read on public.shared_materials for select to authenticated using(status='ready' or uploader_id=auth.uid());
create policy materials_own on public.shared_materials for insert to authenticated with check(uploader_id=auth.uid());
create policy cpu_own on public.cpu_projects to authenticated using(user_id=auth.uid());
create function public.cbgpu_can_use_resource(resource text,target_school text default 'cbsh') returns boolean language sql security definer as $$select false$$;

create table public.contest_award_ballots(contest_id uuid,voter_id uuid);
